<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard · Puihaha Electric</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><style>body{background:#f3f6fb}.topbar{background:#102a56}.brand{color:#fff}.stat{border:0;border-radius:18px;color:#fff;min-height:120px}.table-card,.filter-card{border:0;border-radius:18px;box-shadow:0 8px 24px #102a5610}.badge-active{background:#d1fae5;color:#047857}.badge-inactive{background:#e5e7eb;color:#4b5563}.badge-suspended{background:#fef3c7;color:#92400e}</style></head><body><nav class="navbar topbar navbar-dark"><div class="container"><a class="navbar-brand fw-bold" href="<?= base_url('dashboard') ?>">⚡ Puihaha Electric</a><div class="d-flex align-items-center gap-3 text-white"><span class="small">Signed in as <strong><?= esc($username) ?></strong></span><form method="post" action="<?= base_url('logout') ?>"><button class="btn btn-outline-light btn-sm">Log out</button></form></div></div></nav><main class="container py-4 py-md-5"><div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><p class="text-uppercase text-primary fw-bold small mb-1">Operations console</p><h1 class="fw-bold mb-1">Customer accounts</h1><p class="text-secondary mb-0">Manage connections, meters, and account status.</p></div><a class="btn btn-warning fw-bold" href="<?= base_url('account/new') ?>"><i class="bi bi-plus-lg"></i> Add account</a></div><?php if (!empty($flash)): ?><div class="alert alert-info"><?= esc($flash) ?></div><?php endif; ?><div class="row g-3 mb-4"><div class="col-md-3"><div class="stat p-4" style="background:#164e9b"><div class="small opacity-75">Total accounts</div><div class="display-6 fw-bold"><?= $total_accounts ?></div></div></div><div class="col-md-3"><div class="stat p-4" style="background:#059669"><div class="small opacity-75">Active</div><div class="display-6 fw-bold"><?= $active_accounts ?></div></div></div><div class="col-md-3"><div class="stat p-4" style="background:#64748b"><div class="small opacity-75">Inactive</div><div class="display-6 fw-bold"><?= $inactive_accounts ?></div></div></div><div class="col-md-3"><div class="stat p-4" style="background:#d97706"><div class="small opacity-75">Suspended</div><div class="display-6 fw-bold"><?= $suspended_accounts ?></div></div></div></div><div class="filter-card bg-white p-3 mb-4"><form class="row g-2" method="get" action="<?= base_url('dashboard') ?>"><div class="col-lg-5"><input class="form-control" name="search" placeholder="Search name, account, email, phone" value="<?= esc($search_keyword) ?>"></div><div class="col-lg-2"><select class="form-select" name="status"><option value="">All status</option><?php foreach(['active','inactive','suspended'] as $value): ?><option value="<?= $value ?>" <?= $filter_status===$value?'selected':'' ?>><?= ucfirst($value) ?></option><?php endforeach; ?></select></div><div class="col-lg-2"><select class="form-select" name="type"><option value="">All connection types</option><?php foreach(['residential','commercial','industrial'] as $value): ?><option value="<?= $value ?>" <?= $filter_type===$value?'selected':'' ?>><?= ucfirst($value) ?></option><?php endforeach; ?></select></div><div class="col-lg-2"><button class="btn btn-primary w-100"><i class="bi bi-search"></i> Filter</button></div><div class="col-lg-1"><a class="btn btn-light w-100" href="<?= base_url('dashboard') ?>">Clear</a></div></form></div><div class="table-card bg-white overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th class="ps-4">Account</th><th>Customer</th><th>Contact</th><th>Type</th><th>Status</th><th class="text-end pe-4">Actions</th></tr></thead><tbody><?php if (!$accounts): ?><tr><td colspan="6" class="text-center py-5 text-secondary">No accounts match your filters.</td></tr><?php else: foreach($accounts as $account): ?><tr><td class="ps-4"><strong><?= esc($account['account_number']) ?></strong><div class="small text-secondary"><?= esc($account['meter_number']) ?></div></td><td><?= esc($account['customer_name']) ?><div class="small text-secondary"><?= esc($account['address']) ?></div></td><td><?= esc($account['email']) ?><div class="small text-secondary"><?= esc($account['phone']) ?></div></td><td><span class="text-capitalize"><?= esc($account['connection_type']) ?></span></td><td><span class="badge badge-<?= esc($account['status']) ?> text-capitalize"><?= esc($account['status']) ?></span></td><td class="text-end pe-4"><a class="btn btn-sm btn-outline-primary" href="<?= base_url('account/'.$account['id']) ?>">View</a> <a class="btn btn-sm btn-outline-secondary" href="<?= base_url('account/'.$account['id'].'/edit') ?>">Edit</a></td></tr><?php endforeach; endif; ?></tbody></table></div><div class="d-flex justify-content-between align-items-center p-3 border-top"><span class="small text-secondary">Page <?= esc($current_page) ?> of <?= $pager->getPageCount() ?></span><?= $pager->links() ?></div></div></main></body></html>
